 * not been ended. A removed member keeps their row (archived) for the audit
 * log, so `status` alone does not answer this.
 */
export function isCurrentMember(
  member: Pick<Member, "status" | "archivedAt"> | null | undefined,
): boolean {
  return (
    member !== null &&
    member !== undefined &&
    member.status === "active" &&
    member.archivedAt === null
  );
}
EOF
