add='''/**
 * Clears the assignee on every issue in the org assigned to `userId`, e.g.
 * when they leave. Returns the row count.
 */
export async function unassignIssuesForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set({ assigneeId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.assigneeId, userId)))
