add='''/** Raised when a user is not (or no longer) a current member of the org. */
export class NotAMemberError extends Error {
  readonly code = "forbidden" as const;

  constructor(
    readonly orgId: OrgId,
    readonly userId: UserId,
  ) {
    super(`User ${userId} is not a member of organization ${orgId}`);
    this.name = "NotAMemberError";
  }
}

/**
 * Re-checks the membership behind an `Actor` against stored state, so an actor
 * minted before the member was removed cannot keep acting in the org.
 */
export async function assertActorIsMember(actor: Actor): Promise<void> {
  if (actor.isPlatformStaff === true) return;
  const member = await memberRepo.findMember(actor.orgId, actor.userId);
  if (!isCurrentMember(member)) {
    throw new NotAMemberError(actor.orgId, actor.userId);
  }
}

/**
 * Work can only be handed to a current member of the org: used for issue
 * assignees and project leads. `null` (nobody) is always allowed.
 */
export async function assertAssignableUser(
  orgId: OrgId,
  userId: UserId | null | undefined,
): Promise<void> {
  if (userId === null || userId === undefined) return;
  const member = await memberRepo.findMember(orgId, userId);
  if (!isCurrentMember(member)) {
    throw new NotAMemberError(orgId, userId);
  }
}

/** Keeps only the users who are current members of the org, in order. */
export async function filterCurrentMembers(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<UserId[]> {
  const kept: UserId[] = [];
  for (const userId of userIds) {
    if (isCurrentMember(await memberRepo.findMember(orgId, userId))) {
      kept.push(userId);
    }
  }
  return kept;
}

